</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <cstdio>
#include <iostream>
#include <cmath>
#include <cfloat>
using namespace std;

double compute_abs(double n){
    return n >= 0 ? n : -n;
}

int find_best_a(int x, int y, int b){
    double target_ratio = (double)x / y;
    int low=0, high=1000000;
    for(int i=0; i<25; i++){
        int mid = (low + high) / 2;
        if ((double)mid / b < target_ratio)
            low = mid;
        else
            high = mid;
    }
    int candidate_a;
    double min_difference=DBL_MAX;
    for(int a=low-10; a<=high+10; a++){
        double diff = compute_abs((double)a / b - target_ratio);
        if (diff < min_difference){
            min_difference = diff;
            candidate_a = a;
        }
    }
    return candidate_a;
}

int main(){
    int x,y,n;
    scanf("%d %d %d",&x,&y,&n);
    int best_a, best_b;
    double smallest_diff=DBL_MAX;
    for(int b=1; b<=n; b++){
        int a = find_best_a(x,y,b);
        double diff = compute_abs((double)a/b - (double)x/y);
        if (diff < smallest_diff){
            smallest_diff = diff;
            best_a = a;
            best_b = b;
        }
    }
    printf("%d/%d\n", best_a, best_b);
    return 0;
}
